Arguments: {"cwd":null,"title":"Check PLT products and filters","code":"const tabId = 2017691689;

const info = await browserjs(tabId, () => {
  // Let's find products on PLT search page
  const items = Array.from(document.querySelectorAll('[data-product-id], a[href*=".html"]'));
  const products = [];
  const seen = new Set();

  for (const item of items) {
    const link = item.closest('a') || item.querySelector('a');
    if (!link) continue;
    const href = link.href;
    if (seen.has(href) || !href.includes('.html')) continue;
    seen.add(href);

    const card = link.closest('[class*="product"]') || link;
    const title = card.querySelector('[class*="title"], [class*="name"]')?.textContent?.trim() || link.getAttribute('title') || link.textContent?.trim();
    const price = card.querySelector('[class*="price"]')?.textContent?.trim();
    if (title && title.toLowerCase().includes('green')) {
      products.push({ title, price, href });
    }
  }

  // Also check filters
  const filterButtons = Array.from(document.querySelectorAll('button, div[class*="filter"]'))
    .map(el => el.textContent?.trim())
    .filter(t => t && (t.toLowerCase().includes('size') || t.toLowerCase().includes('colour') || t.toLowerCase().includes('filter')));

  return { productCount: products.length, products: products.slice(0, 10), filterButtons: filterButtons.slice(0, 10) };
});

console.log(JSON.stringify(info, null, 2));
"}
