Arguments: {"cwd":null,"code":"const tabId = 2017691689;

const productElements = await browserjs(tabId, () => {
  // Let's search for the text "CHIFFON TRIM DETAIL DRAPE MAXI DRESS"
  const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
  let node;
  const matches = [];
  while ((node = walker.nextNode())) {
    if (node.textContent.includes("CHIFFON TRIM DETAIL DRAPE MAXI DRESS")) {
      let el = node.parentElement;
      // let's climb up to find a container or link
      let path = [];
      let curr = el;
      while (curr && curr !== document.body) {
        path.push({
          tag: curr.tagName,
          className: curr.className,
          href: curr.href || null,
          role: curr.getAttribute('role')
        });
        curr = curr.parentElement;
      }
      matches.push({ text: node.textContent, path });
    }
  }
  return matches;
});

console.log(JSON.stringify(productElements, null, 2));
